/**
 * Точка входа вендорного BPMN Client SDK.
 *
 * Каталог — приёмник собранного артефакта: `bpmn-sdk.umd.js` и
 * `BUILD_INFO.json` генерируются командами
 * `npm run sdk:build` / `npm run sdk:sync` из `src/bpmn-sdk`.
 * Править их руками бессмысленно — правки затрутся при следующей
 * синхронизации; исходники SDK живут в `src/bpmn-sdk` (см. `README.md`).
 *
 * Импорт идёт через этот файл, а не напрямую в бандл, потому что:
 *  - относительный импорт каталога требует `index.js` либо `main`
 *    в `package.json`, а добавлять `module`/`exports` в `src/bpmn-sdk`
 *    нельзя: тогда относительный импорт SDK в CRA получил бы ESM-сборку
 *    с внешними `bpmn-js` и без стилей;
 *  - UMD отдаёт `module.exports` целиком, поэтому `require` здесь —
 *    единственный способ не дублировать список из 11 экспортов.
 */

module.exports = require('./bpmn-sdk.umd.js');
